import { describe, expect, it } from 'vitest';
import { renderSummary } from './report.js';
import { GateResult, Finding } from './schema.js';

describe('renderSummary', () => {
  it('renders PASS 7/7 when all checks pass', () => {
    const result: GateResult = {
      verdict: 'PASS',
      tier: 'limited',
      findings: [],
      gateSection: '# Gate section'
    };
    expect(renderSummary(result)).toBe('PASS 7/7');
  });

  it('renders WARN 6/7 with warning in evaluation', () => {
    const result: GateResult = {
      verdict: 'WARN',
      tier: 'limited',
      findings: [
        {
          checkId: 'evaluation',
          severity: 'warn',
          message: 'No numbers in evaluation',
          source: 'validator'
        }
      ],
      gateSection: '# Gate section'
    };
    expect(renderSummary(result)).toBe('WARN 6/7: evaluation');
  });

  it('renders BLOCK 5/7 with block findings in evaluation and transparency', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'evaluation',
          severity: 'block',
          message: 'Missing evaluation plan',
          source: 'validator'
        },
        {
          checkId: 'transparency',
          severity: 'block',
          message: 'Missing transparency section',
          source: 'validator'
        }
      ],
      gateSection: '# Gate section'
    };
    expect(renderSummary(result)).toBe('BLOCK 5/7: evaluation, transparency');
  });

  it('renders BLOCK 0/7 when gate section is missing', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'structure',
          severity: 'block',
          message: 'No gate section found',
          source: 'validator'
        }
      ],
      gateSection: null
    };
    expect(renderSummary(result)).toBe('BLOCK 0/7: structure');
  });

  it('renders BLOCK 4/7 with multiple block checks', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'risk-tier',
          severity: 'block',
          message: 'Missing risk tier',
          source: 'validator'
        },
        {
          checkId: 'evaluation',
          severity: 'block',
          message: 'Missing evaluation plan',
          source: 'validator'
        },
        {
          checkId: 'monitoring',
          severity: 'block',
          message: 'Missing monitoring section',
          source: 'validator'
        }
      ],
      gateSection: '# Gate section'
    };
    expect(renderSummary(result)).toBe('BLOCK 4/7: risk-tier, evaluation, monitoring');
  });

  it('renders WARN with multiple warning findings', () => {
    const result: GateResult = {
      verdict: 'WARN',
      tier: 'limited',
      findings: [
        {
          checkId: 'evaluation',
          severity: 'warn',
          message: 'No numbers in evaluation',
          source: 'validator'
        },
        {
          checkId: 'monitoring',
          severity: 'warn',
          message: 'Monitoring lacks specificity',
          source: 'validator'
        }
      ],
      gateSection: '# Gate section'
    };
    expect(renderSummary(result)).toBe('WARN 5/7: evaluation, monitoring');
  });

  it('respects GATE_CHECKS order for check ids', () => {
    // Create findings in reverse GATE_CHECKS order to verify they are sorted
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'transparency',
          severity: 'block',
          message: 'Missing transparency',
          source: 'validator'
        },
        {
          checkId: 'risk-tier',
          severity: 'block',
          message: 'Missing risk tier',
          source: 'validator'
        }
      ],
      gateSection: '# Gate section'
    };
    // Should be in GATE_CHECKS order: risk-tier comes before transparency
    expect(renderSummary(result)).toBe('BLOCK 5/7: risk-tier, transparency');
  });

  it('deduplicates check ids from multiple findings', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'evaluation',
          severity: 'block',
          message: 'Missing evaluation plan',
          source: 'validator'
        },
        {
          checkId: 'evaluation',
          severity: 'block',
          message: 'Evaluation lacks numbers',
          source: 'agent'
        }
      ],
      gateSection: '# Gate section'
    };
    expect(renderSummary(result)).toBe('BLOCK 6/7: evaluation');
  });

  it('handles mixed block and warn findings', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'risk-tier',
          severity: 'block',
          message: 'Missing risk tier',
          source: 'validator'
        },
        {
          checkId: 'evaluation',
          severity: 'warn',
          message: 'No numbers in evaluation',
          source: 'validator'
        }
      ],
      gateSection: '# Gate section'
    };
    // Both block and warn reduce the answered count
    expect(renderSummary(result)).toBe('BLOCK 5/7: risk-tier, evaluation');
  });
});

