 }
+
+export function renderSummary(result: GateResult): string {
+  const TOTAL = GATE_CHECKS.length;
+
+  // Special case: missing gate section
+  if (result.gateSection === null) {
+    return `BLOCK 0/${TOTAL}: structure`;
+  }
+
+  // Get unique check IDs with findings, in GATE_CHECKS order
+  const checksWithFindings = new Set(result.findings.map((f) => f.checkId));
+  const blockedCheckIds: string[] = [];
+
+  for (const check of GATE_CHECKS) {
+    if (checksWithFindings.has(check.id)) {
+      blockedCheckIds.push(check.id);
+    }
+  }
+
+  // Calculate answered count (checks with no findings)
+  const answered = TOTAL - blockedCheckIds.length;
+
+  // Format output
+  if (blockedCheckIds.length === 0) {
+    return `${result.verdict} ${answered}/${TOTAL}`;
+  } else {
+    return `${result.verdict} ${answered}/${TOTAL}: ${blockedCheckIds.join(', ')}`;
+  }
+}

