import { describe, expect, it } from 'vitest';
import { renderSummary } from './report.js';
import { GateResult, Finding } from './schema.js';

describe('renderSummary', () => {
  it('renders PASS 7/7 when all checks pass', () => {
    const result: GateResult = {
      verdict: 'PASS',
      tier: 'limited',
      findings: [],
      gateSection: '# Gate section'
    };
    expect(renderSummary(result)).toBe('PASS 7/7');
  });

  it('renders WARN 7/7 when only warnings present (warnings do not reduce answered)', () => {
    const result: GateResult = {
      verdict: 'WARN',
      tier: 'limited',
      findings: [
        {
          checkId: 'evaluation',
          severity: 'warn',
          message: 'No numbers in evaluation',
          source: 'validator'
        }
      ],
      gateSection: '# Gate section'
    };
    expect(renderSummary(result)).toBe('WARN 7/7');
  });

  it('renders WARN 7/7 with multiple warning findings (no IDs listed for warnings)', () => {
    const result: GateResult = {
      verdict: 'WARN',
      tier: 'limited',
      findings: [
        {
          checkId: 'evaluation',
          severity: 'warn',
          message: 'No numbers in evaluation',
          source: 'validator'
        },
        {
          checkId: 'monitoring',
          severity: 'warn',
          message: 'Monitoring lacks specificity',
          source: 'validator'
        }
      ],
      gateSection: '# Gate section'
    };
    expect(renderSummary(result)).toBe('WARN 7/7');
  });

  it('renders BLOCK 5/7 with block findings in evaluation and transparency', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'evaluation',
          severity: 'block',
          message: 'Missing evaluation plan',
          source: 'validator'
        },
        {
          checkId: 'transparency',
          severity: 'block',
          message: 'Missing transparency section',
          source: 'validator'
        }
      ],
      gateSection: '# Gate section'
    };
    expect(renderSummary(result)).toBe('BLOCK 5/7: evaluation, transparency');
  });

  it('renders BLOCK 0/7 when gate section is missing', () => {
    const result: GateResult = {
